mapper.sql:
WHERE d.del_flag = '0'

    AND d.project_id = #{defect.projectId}


    AND d.defect_name LIKE CONCAT('%', #{defect.defectName}, '%')


    AND d.defect_state = #{defect.defectState}


    AND d.defect_state IN
    #{state}


    AND d.defect_type = #{defect.defectType}


    AND d.module_id = #{defect.moduleId}


    AND d.project_num = #{defect.params.projectNum}


    AND CONCAT(',', REPLACE(REPLACE(REPLACE(d.handle_by, '[', ''), ']', ''), ' ', ''), ',')
        LIKE CONCAT('%,', #{defect.params.handleById}, ',%')

mapper.select:
SELECT





    ORDER BY ${_pageOrder}
    ORDER BY d.defect_id DESC

LIMIT #{limit} OFFSET #{offset}

SELECT


WHERE d.project_id = #{projectId}
  AND d.project_num = #{projectNum}
  AND d.del_flag = '0'
LIMIT 1
